  };

  const r = applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher rejects null invoice', () => {
  const r = applyVoucher(null, { code: 'SUMMER2026', amount: 5000 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('applyVoucher prevents multiple vouchers', () => {
