    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const withFirstVoucher = applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 }).value;
  const r = applyVoucher(withFirstVoucher, { code: 'SPRING2026', amount: 3000 });

  assert.deepEqual(r, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher does not mutate original invoice', () => {
