test('balanceDue accounts for vouchers', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SUMMER2026', amount: 5000 }).value;
  const issued = issueInvoice(withVoucher, []).value;

  const totalWithoutVoucher = invoiceTotals(issued).value.total;
  const totalWithVoucher = invoiceTotals(withVoucher).value.total;
  const balance = balanceDue(issued);

  assert.equal(balance, totalWithVoucher);
  assert.equal(balance, totalWithoutVoucher - 5000);
});

test('balanceDue with voucher and payment', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
