  const payment = recordPayment(issued, { amount: 10000, date: '2026-10-08' }).value;
  const balance = balanceDue(payment);
  const totalAfterVoucher = invoiceTotals(issued).value.total;

  assert.equal(balance, totalAfterVoucher - 10000);
